const connections = {
  active: 0,
  open() {
    this.active += 1;
    let closed = false;
    return () => {
      if (!closed) { this.active -= 1; closed = true; }
    };
  }
};
function Listener() {
  React.useEffect(() => {
    const close = connections.open();
    return close;
  }, []);
  return <p>Listener mounted</p>;
}
